def table(df):
 if not len(df):return '当前没有符合这一条件的结果；不补造通过项。'
 def fmt(x):
  if pd.isna(x):return 'NA'
  if isinstance(x,(float,np.floating)):return f'{x:.6g}'
  return str(x).replace('|','／').replace('\n',' ')
 return '| '+' | '.join(str(c) for c in df.columns)+' |\n| '+' | '.join('---' for c in df.columns)+' |\n'+'\n'.join('| '+' | '.join(fmt(x) for x in row)+' |' for row in df.itertuples(index=False,name=None))
